input.command:
cd /c/visual\ projects/alpha/data/tk411; 
head1() { s=$(curl -sI -m 20 "$2" | tr -d '\r' | awk -F': ' 'tolower($1)=="content-length"{l=$2} /^HTTP/{c=$2} END{print c"\t"l}'); printf '%s\t%s\t%s\n' "$1" "$3" "$s"; }
export -f head1
( while read c; do echo "fut $c https://download.gatedata.org/futures_usdt/trades/202609/$c-202609.csv.gz"; done < fut.lst
  while read c; do echo "spot $c https://download.gatedata.org/spot/deals/202609/$c-202609.csv.gz"; done < spot.lst ) | 
 xargs -P 6 -L1 bash -c 'curl -sI -m 20 "$2" | tr -d "\r" | awk -v k="$0" -v c="$1" -F": " "tolower(\$1)==\"content-length\"{l=\$2} /^HTTP/{h=\$2} END{print k\"\t\"c\"\t\"h\"\t\"l}"' > heads.tsv 2>/dev/null; wc -l heads.tsv; head -3 heads.tsv

