input.command:
cd /c/visual\ projects/alpha/data/tk411; python -I -c "
import json
q={x['name']:x['quanto_multiplier'] for x in json.load(open('fc.json'))}
o=[]
for l in open('heads.tsv',encoding='utf-8'):
    k,c,h,s=l.rstrip('\n').split('\t')
    if h=='200': o.append('%s\t%s\t%s\n'%(k,c,q[c] if k=='fut' else '1'))
open('gate-list.tsv','w',encoding='utf-8',newline='\n').writelines(o); print(len(o))
" ; grep -c . gate-list.tsv; grep -P "[^\x00-\x7f]" gate-list.tsv | head; cd ..; tar -cf tk411.tar -C tk411 gate-list.tsv -C ../../tools/compute tk411-gate-dl.sh tk411-gate-build.sh tk411-gate-candles.py && ls -l tk411.tar

